import{_ as t,o as i,c as l,ai as a,j as e,cN as s,cO as n}from"./chunks/framework.C9qw1mHn.js";const y=JSON.parse('{"title":"Binary Search Trees: Traversal","description":"","frontmatter":{},"headers":[],"relativePath":"lectures/14-binary-trees-traversal.md","filePath":"lectures/14-binary-trees-traversal.md","lastUpdated":1772598826000}'),o={name:"lectures/14-binary-trees-traversal.md"};function d(p,r,h,c,m,u){return i(),l("div",null,[...r[0]||(r[0]=[a('<h1 id="binary-search-trees-traversal" tabindex="-1">Binary Search Trees: Traversal <a class="header-anchor" href="#binary-search-trees-traversal" aria-label="Permalink to “Binary Search Trees: Traversal”">​</a></h1><p>Chapter 19</p><h2 id="what-and-why" tabindex="-1">What and why: <a class="header-anchor" href="#what-and-why" aria-label="Permalink to “What and why:”">​</a></h2><ul><li><strong>Visit</strong> every node in a BST exactly once.</li><li><strong>Common orders</strong>: in-order, pre-order, post-order (depth-first); level-order (breadth-first).</li><li><strong>Uses</strong>: produce sorted output, copy or delete a tree, compute aggregates (size, sum, height).</li></ul><h2 id="lecture-video" tabindex="-1">Lecture Video <a class="header-anchor" href="#lecture-video" aria-label="Permalink to “Lecture Video”">​</a></h2>',5),e("div",{class:"youtube"},[e("div",null,[e("iframe",{width:"853",height:"480",src:"https://www.youtube-nocookie.com/embed/ivETILrEJ_Y?rel=0&showinfo=0",title:"CSCI 315",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:"allowfullscreen"})])],-1),a('<h2 id="traversal-orders" tabindex="-1">Traversal Orders <a class="header-anchor" href="#traversal-orders" aria-label="Permalink to “Traversal Orders”">​</a></h2><p><em><strong>Traversing</strong></em> a tree means “<em><strong>visiting</strong></em>” each node exactly once.</p><p>We may visit each the nodes in a tree to determine its size, display it, update it, delete it, sum the values, etc.</p><p>We can visit the notes in various orders.</p><ul><li><p>In-order</p><ol><li>Traverse the left subtree.</li><li><em>Visit the node.</em></li><li>Traverse the right subtree.</li></ol></li><li><p>Pre-order</p><ol><li><em>Visit the node.</em></li><li>Traverse the left subtree.</li><li>Traverse the right subtree.</li></ol></li><li><p>Post-order</p><ol><li>Traverse the left subtree.</li><li>Traverse the right subtree.</li><li><em>Visit the node.</em></li></ol></li></ul><h3 id="example-of-binary-tree-traversal" tabindex="-1">Example of Binary Tree Traversal <a class="header-anchor" href="#example-of-binary-tree-traversal" aria-label="Permalink to “Example of Binary Tree Traversal”">​</a></h3><ul><li>Input (one example): <code>E C F A D H B G</code></li></ul><figure class="light-only"><img src="'+s+'" alt="Binary tree created from example input" class="light-only"><figcaption>Binary tree created from example input</figcaption></figure><figure class="dark-only"><img src="'+n+'" alt="Binary tree created from example input" class="dark-only"><figcaption>Binary tree created from example input</figcaption></figure><ul><li><p>In-order sequence: <code>A B C D E F G H</code></p></li><li><p>Pre-order sequence: <code>E C A B D F H G</code></p><ul><li>(Useful for copying a tree and preserving the structure.)</li></ul></li><li><p>Post-order sequence: <code>B A D C G H F E</code></p><ul><li>(Useful for deleting a subtree.)</li></ul></li></ul><h3 id="depth-and-breadth-first-traversals" tabindex="-1">Depth- and Breadth-First Traversals <a class="header-anchor" href="#depth-and-breadth-first-traversals" aria-label="Permalink to “Depth- and Breadth-First Traversals”">​</a></h3><p>The in-order, pre-order, and post-order traversals we implemented are <em>depth</em>-first traversals.</p><p>We could also use a queue to implement a <em>level</em>-based (<em>breadth</em>-first) traversal.</p><h2 id="typical-operations-on-binary-tree" tabindex="-1">Typical Operations on Binary Tree <a class="header-anchor" href="#typical-operations-on-binary-tree" aria-label="Permalink to “Typical Operations on Binary Tree”">​</a></h2><ul><li><p>Determine whether the binary tree is empty.</p></li><li><p>Insert an item in the binary tree.</p></li><li><p>Delete an item from the binary tree.</p></li><li><p>Search the binary tree for a particular item.</p></li><li><p>Find the height of the binary tree.</p></li><li><p>Find the number of nodes in the binary tree.</p></li><li><p>Find the number of leaves in the binary tree.</p></li><li><p>Traverse the binary tree.</p></li><li><p>Copy the binary tree.</p></li></ul><h2 id="lab-14-binary-trees-part-1" tabindex="-1">Lab 14: Binary Trees (Part 1) <a class="header-anchor" href="#lab-14-binary-trees-part-1" aria-label="Permalink to “Lab 14: Binary Trees (Part 1)”">​</a></h2><p>Let’s take a look at the lab based on today’s lecture.</p>',17)])])}const f=t(o,[["render",d]]);export{y as __pageData,f as default};
